import{_ as i,a0 as o,w as u,s as r,ao as p,I as e,x as n,a1 as s,A as a}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const T=JSON.parse('{"title":"Linux上最先进的免费赛车游戏：StuntRally 2.4 | LCTT x X-CMD","titleTemplate":false,"description":"Linux上最先进的免费赛车游戏：StuntRally 2.4 | LCTT (201408) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux上最先进的免费赛车游戏：StuntRally 2.4 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux上最先进的免费赛车游戏：StuntRally 2.4 | LCTT (201408) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201408/20140811 StuntRally 2.4 Is the Most Advanced Free Racing Game on Linux","title":"Linux上最先进的免费赛车游戏：StuntRally 2.4","tag":"201408","desc":""},"relativePath":"201408/20140811 StuntRally 2.4 Is the Most Advanced Free Racing Game on Linux.md","filePath":"[post].md"}'),d={name:"201408/20140811 StuntRally 2.4 Is the Most Advanced Free Racing Game on Linux.md"};function m(f,t,x,y,R,S){const l=o("Link");return u(),r("div",null,[t[18]||(t[18]=p('<h1 id="linux上最先进的免费赛车游戏-stuntrally-2-4" tabindex="-1">Linux上最先进的免费赛车游戏：StuntRally 2.4 <a class="header-anchor" href="#linux上最先进的免费赛车游戏-stuntrally-2-4" aria-label="Permalink to “Linux上最先进的免费赛车游戏：StuntRally 2.4”">​</a></h1><p><img src="http://i1-news.softpedia-static.com/images/news2/StuntRally-2-4-Is-the-Most-Advance-Free-Racing-Game-on-Linux-454345-2.jpg" alt="StuntRally"> StuntRally</p><p><strong>StuntRally，免费的赛车游戏，拥有超过150个赛道和大量的车型，刚刚发布2.4版本，并带来大量的更新和新功能。</strong></p><p>这个游戏使用了多项技术， 例如 Vdrift、物理引擎 bullet、面向对象图形渲染引擎 OGRE、 网格的渲染优化 PagedGeometry 和 MyGUI 等等，不一一列举，开发者将其全部整合在一起构造了一个非常复杂和有趣的赛车游戏.</p><p>玩家可以在147个赛道和26个不同的场景中游戏，总计有四个小时的车程时间。在如此多的选择下，你要知道，而StuntRally是完全免费的！</p><p>其他功能包括在幽灵驾驶（可以跟踪你的车子在赛道上的最佳瞬间），赛道幽灵（赛道上的最佳驾驶，一个绿幽灵赛车，可以出现在所有轨道），回放（记录你的驾驶过程，并可以从其它的摄像头角度查看），许多的教程，几个总冠军杯赛，一些挑战赛，分屏赛车，和多人游戏。</p><p>最重要的是，开发商还提供了一个轨道编辑器，允许用户实时编辑道路节点及其参数，改变所有的赛道参数，调整地形生成器，甚至修改驾驶中的汽车的属性。</p><p>根据更新日志，添加了6个新的地图，删除了12个旧关卡，更新了一些赛道，增加了两个名为Crystals 和 GreeceWhite的场景，实现了太空飞船式气垫船，一半的赛道添加了新的天空纹理贴图，一些赛道上的静态景物现在可以用了，汽车属性页有了状态条、速度图，并添加了一个短列表视图。</p><p>同时，字体现在他们已重新调整得更大了，增加了包括胜利、失败、过圈最佳时间和故障检测排除等声音，已修复了多人游戏中用户昵称出现两次的问题，在一些赛道实现了地形、浓雾、水体的影响，关卡编辑器已经做了一些改进，汽车转向控制进行了改进，修复了游戏中的汽车表面调整窗口。</p>',9)),e("p",null,[t[1]||(t[1]=n("关于StuntRally更多最新消息可以参考 ",-1)),s(l,{href:"https://code.google.com/p/vdrift-ogre/wiki/VersionHistory"},{default:a(()=>[...t[0]||(t[0]=[n("通告",-1)])]),_:1}),t[2]||(t[2]=n("。",-1))]),t[19]||(t[19]=e("p",null,"下载 StuntRally 2.4:",-1)),e("ul",null,[e("li",null,[s(l,{href:"http://sourceforge.net/projects/stuntrally/files/2.4/StuntRally-2.4-linux64.tar.xz/download"},{default:a(()=>[...t[3]||(t[3]=[n("Stunt Rally 2.4 tar.xz",-1)])]),_:1}),t[4]||(t[4]=n("[binary] [735 MB]",-1))])]),t[20]||(t[20]=e("hr",null,null,-1)),e("p",null,[t[6]||(t[6]=n("via: ",-1)),s(l,{href:"http://news.softpedia.com/news/StuntRally-2-4-Is-the-Most-Advance-Free-Racing-Game-on-Linux-454345.shtml"},{default:a(()=>[...t[5]||(t[5]=[n("http://news.softpedia.com/news/StuntRally-2-4-Is-the-Most-Advance-Free-Racing-Game-on-Linux-454345.shtml",-1)])]),_:1})]),e("p",null,[t[10]||(t[10]=n("作者：",-1)),s(l,{href:"http://news.softpedia.com/editors/browse/silviu-stahie"},{default:a(()=>[...t[7]||(t[7]=[n("Silviu Stahie",-1)])]),_:1}),t[11]||(t[11]=n(" 译者：",-1)),s(l,{href:"https://github.com/fbigun"},{default:a(()=>[...t[8]||(t[8]=[n("fbigun",-1)])]),_:1}),t[12]||(t[12]=n(" 校对：",-1)),s(l,{href:"https://github.com/wxy"},{default:a(()=>[...t[9]||(t[9]=[n("wxy",-1)])]),_:1})]),e("p",null,[t[15]||(t[15]=n("本文由 ",-1)),s(l,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...t[13]||(t[13]=[n("LCTT",-1)])]),_:1}),t[16]||(t[16]=n(" 原创翻译，",-1)),s(l,{href:"http://linux.cn/"},{default:a(()=>[...t[14]||(t[14]=[n("Linux中国",-1)])]),_:1}),t[17]||(t[17]=n(" 荣誉推出",-1))])])}const C=i(d,[["render",m]]);export{T as __pageData,C as default};
